import { useState } from 'react';

export function ProfileForm({ initial, onSave }) {
  const [form, setForm] = useState(initial);
  const isDirty = Object.keys(initial).some((key) => form[key] !== initial[key]);

  const handleChange = (e) => setForm((f) => ({ ...f, [e.target.name]: e.target.value }));

  return (
    <form onSubmit={(e) => { e.preventDefault(); onSave(form); }}>
      <label>Imię <input name="name" value={form.name} onChange={handleChange} /></label>
      <label>Miasto <input name="city" value={form.city} onChange={handleChange} /></label>
      <button type="submit" disabled={!isDirty}>Zapisz</button>
      <button type="button" disabled={!isDirty} onClick={() => setForm(initial)}>Przywróć</button>
    </form>
  );
}

export function ProfilePage({ profile, onSave }) {
  // Nowy id = nowa instancja formularza = świeży stan z initial.
  return <ProfileForm key={profile.id} initial={profile} onSave={onSave} />;
}

