import { useState, type ChangeEvent, type FormEvent } from 'react';

type Form = { name: string; email: string };
type Status = 'idle' | 'saving' | 'saved' | 'error';

function fakeSave(data: Form): Promise<void> {
  return new Promise((resolve, reject) => {
    setTimeout(() => (data.email.includes('fail') ? reject(new Error('Serwer odrzucił zapis')) : resolve()), 800);
  });
}

const EMPTY: Form = { name: '', email: '' };

export function SaveForm() {
  const [form, setForm] = useState(EMPTY);
  const [status, setStatus] = useState<Status>('idle');
  const [error, setError] = useState('');

  const handleChange = (e: ChangeEvent<HTMLInputElement>) => setForm((f) => ({ ...f, [e.target.name]: e.target.value }));

  async function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setStatus('saving');
    try {
      await fakeSave(form);
      setStatus('saved');
      setForm(EMPTY);
    } catch (err) {
      // W TS błąd w catch ma typ unknown — sprawdzamy, czy to Error.
      setError(err instanceof Error ? err.message : 'Nieznany błąd');
      setStatus('error');
    }
  }

  return (
    <form onSubmit={handleSubmit}>
      <fieldset disabled={status === 'saving'}>
        <label>Imię <input name="name" value={form.name} onChange={handleChange} /></label>
        <label>E-mail <input name="email" value={form.email} onChange={handleChange} /></label>
        <button type="submit">{status === 'saving' ? 'Zapisywanie…' : 'Zapisz'}</button>
      </fieldset>
      {status === 'saved' && <p role="status">Zapisano!</p>}
