export function WorkshopForm({onSubmit}:{onSubmit:(payload:Payload)=>Promise<void>}){const [form,setForm]=useState(initial);const [submitted,setSubmitted]=useState(false);const [status,setStatus]=useState<"idle"|"saving"|"saved"|"error">("idle");const id=useId();const errors=validate(form);const count=seatsCount(form.seats);const error=(field:keyof Workshop)=>submitted?errors[field]:undefined;const props=(field:keyof Workshop)=>({"aria-invalid":error(field)?true:undefined,"aria-describedby":error(field)?id+"-"+field:undefined});const message=(field:keyof Workshop)=>error(field)?<p id={id+"-"+field}>{error(field)}</p>:null;return <form noValidate onSubmit={async event=>{event.preventDefault();if(status==="saving")return;setSubmitted(true);const payload=toPayload(form);if(payload===null)return;setStatus("saving");try{await onSubmit(payload);setStatus("saved");}catch{setStatus("error");}}}><fieldset disabled={status==="saving"}><legend>Zapis na warsztaty</legend><label>Imię<input value={form.name} onChange={event=>{const name=event.currentTarget.value;setForm(f=>({...f,name}));}} {...props("name")}/></label>{message("name")}<label>E-mail<input type="email" value={form.email} onChange={event=>{const email=event.currentTarget.value;setForm(f=>({...f,email}));}} {...props("email")}/></label>{message("email")}<fieldset><legend>Poziom</legend>{(["beginner","intermediate","advanced"] as const).map(level=><label key={level}><input type="radio" name={id+"-level"} checked={form.level===level} onChange={()=>setForm(f=>({...f,level}))}/>{level}</label>)}</fieldset><label>Format<select value={form.format} onChange={event=>{const value=event.currentTarget.value;if(value==="online"||value==="onsite")setForm(f=>({...f,format:value}));}}><option>online</option><option>onsite</option></select></label><label>Uwagi<textarea value={form.notes} onChange={event=>{const notes=event.currentTarget.value;setForm(f=>({...f,notes}));}}/></label><label>Miejsca<input type="number" min={1} max={5} step={1} value={form.seats} onChange={event=>{const seats=event.currentTarget.value;setForm(f=>({...f,seats}));}} {...props("seats")}/></label>{message("seats")}{count!==null&&<p>Cena: {new Intl.NumberFormat("pl-PL",{style:"currency",currency:"PLN"}).format(count*120)}</p>}<fieldset {...props("topics")}><legend>Tematy</legend>{TOPICS.map(topic=><label key={topic}><input type="checkbox" checked={form.topics.includes(topic)} onChange={()=>setForm(f=>({...f,topics:toggleTopic(f.topics,topic)}))}/>{topic}</label>)}</fieldset>{message("topics")}<label>Kraj<select value={form.country} onChange={event=>{const country=event.currentTarget.value;if(country==="PL"||country==="DE")setForm(f=>changeCountry(f,country));}}><option>PL</option><option>DE</option></select></label><label>Region<select value={form.region} onChange={event=>{const region=event.currentTarget.value;setForm(f=>({...f,region}));}} {...props("region")}><option value="">Nie wybrano</option>{REGIONS[form.country].map(region=><option key={region}>{region}</option>)}</select></label>{message("region")}<label>Polski kod pocztowy<input inputMode="numeric" value={form.postal} onChange={event=>{const postal=postalCode(event.currentTarget.value);setForm(f=>({...f,postal}));}}/></label><fieldset><legend>Telefony kontaktowe</legend>{form.phones.map(phone=><div key={phone.id}><label>Telefon {phone.id}<input type="tel" value={phone.value} onChange={event=>{const value=event.currentTarget.value;setForm(f=>editPhone(f,phone.id,value));}}/></label><button type="button" onClick={()=>setForm(f=>removePhone(f,phone.id))}>Usuń telefon {phone.id}</button></div>)}<button type="button" onClick={()=>setForm(addPhone)}>Dodaj telefon</button></fieldset><label><input type="checkbox" checked={form.terms} onChange={event=>{const terms=event.currentTarget.checked;setForm(f=>({...f,terms}));}} {...props("terms")}/>Akceptuję regulamin</label>{message("terms")}<button type="submit">{status==="saving"?"Zapisywanie…":"Zapisz się"}</button><button type="button" onClick={()=>{setForm(initial());setSubmitted(false);setStatus("idle");}}>Wyczyść</button></fieldset>{status==="saved"&&<p role="status">Zapisano zgłoszenie.</p>}{status==="error"&&<p role="alert">Zapis nieudany. Dane zachowano.</p>}</form>;}

