export function validate(form:Workshop):Errors{const errors:Errors={};if(form.name.trim().length<2)errors.name="Podaj imię.";if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(form.email.trim()))errors.email="Podaj e-mail.";if(seatsCount(form.seats)===null)errors.seats="Miejsca: 1–5.";if(!form.topics.length)errors.topics="Wybierz temat.";if(!form.terms)errors.terms="Zaakceptuj regulamin.";if(form.region&&!REGIONS[form.country].includes(form.region))errors.region="Region nie pasuje do kraju.";return errors;}
export function toPayload(form:Workshop):Payload|null{if(Object.keys(validate(form)).length)return null;const count=seatsCount(form.seats);if(count===null)return null;const {nextPhoneId,seats,...rest}=form;return {...rest,name:form.name.trim(),email:form.email.trim(),seats:count,topics:[...form.topics],phones:form.phones.map(phone=>({...phone}))};}
